25	impl Jump {
26	    fn from_span(world: &dyn IdeWorld, span: Span) -> Option<Self> {
27	        let id = span.id()?;
28	        let offset = world.range(span)?.start;
29	        Some(Self::File(id, offset))
30	    }
31	}
