33	/// Determine where to jump to, based on a click in a rendered document.
34	pub fn jump_from_click<D: JumpFromDocument>(
35	    world: &dyn IdeWorld,
36	    document: &D,
37	    position: &D::Position,
38	) -> Option<Jump> {
39	    document.resolve_position(world, position)
40	}
