373	/// Sealing for [`JumpInDocument`].
374	mod jump_in_document_sealed {
375	    use std::num::NonZeroUsize;
376	
377	    use ecow::EcoVec;
378	    use typst::introspection::{HtmlPosition, PagedPosition};
379	    use typst::syntax::Span;
