3. Shape branch (L292-320):
```rust
FrameItem::Shape(shape, span) => {
    if shape.fill.is_some() {
        let within = match &shape.geometry {
            Geometry::Line(..) => false,
            Geometry::Rect(size) => is_in_rect(pos, *size, click),
            Geometry::Curve(curve) => {
