            return Jump::from_span(world, *span);
        }
    }

    if let Some(stroke) = &shape.stroke {
        let within = !stroke.thickness.approx_empty() && {
            let base_curve = match &shape.geometry {
                Geometry::Line(to) => &Curve(vec![CurveItem::Line(*to)]),
                Geometry::Rect(size) => &Curve::rect(*size),
                Geometry::Curve(curve) => curve,
            };
            base_curve.stroke_contains(stroke, click - pos)
        };
        if within {
            return Jump::from_span(world, *span);
        }
    }
}
```

Key points:
- Fill hit-test: Line → never (a line has no interior); Rect → is_in_rect; Curve → `curve.contains(fill_rule, click - pos)`. Note the curve is rooted at origin (0,0), so `click - pos` translates the click into the shape's local coords.
- Stroke hit-test: first skip if stroke thickness is ~0 (`approx_empty()`). Then convert geometry to a base Curve (Line → single line segment, Rect → rectangle curve, Curve → as-is), and call `stroke_contains(stroke, click - pos)`.
- Both return `Jump::from_span(world, *span)`.

